mapper.select:
SELECT id, stock_code AS code, trade_time, price, volume, amount, avg_price
FROM minute_quote
WHERE stock_code = #{code}
  AND trade_time >= #{date}
  AND trade_time < DATE_ADD(#{date}, INTERVAL 1 DAY)
ORDER BY trade_time

SELECT id, stock_code AS code, date, open, high, low, close, pre_close, volume, amount
FROM daily_quote
WHERE date = #{date}

SELECT id, stock_code AS code, date, open, high, low, close, pre_close, volume, amount
FROM daily_quote
WHERE stock_code = #{code}

    AND date < #{endDate}

ORDER BY date DESC
LIMIT #{limit}

SELECT id, stock_code AS code, date, open, high, low, close, pre_close, volume, amount
FROM daily_quote
WHERE stock_code = #{code}
  AND date < #{beforeDate}
ORDER BY date DESC
LIMIT #{limit}

SELECT stock_code AS code, date, volume
FROM daily_quote
WHERE date IN (
    SELECT date FROM (
        SELECT DISTINCT date FROM daily_quote
        WHERE date < #{beforeDate}
        ORDER BY date DESC
        LIMIT #{days}
    ) t
)

SELECT id, stock_code AS code, date, open, high, low, close, pre_close, volume, amount
FROM daily_quote
WHERE stock_code = #{code}
  AND date = #{date}

SELECT id, stock_code AS code, trade_time, price, volume, amount, avg_price
FROM minute_quote
WHERE stock_code = #{code}

    AND trade_time < #{endTime}

ORDER BY trade_time DESC
LIMIT #{limit}
